import Foundation

/// Carrying an earlier version's files into this one. Earlier versions wrote
/// their startup files where the tools look by default, so a "Generated by
/// Macarchy" file there is Macarchy's own, and only its keep region is the
/// person's. That region carries over whichever way setup starts, because
/// dropping it would lose their commands without a word.
extension Setup {
    /// The person's lines from an earlier version's startup file: its keep
    /// regions, `yours` first, with paths into the old folder rewritten.
    static func carriedRegion(from source: URL, report: inout [String]) throws -> String {
        let text = try String(contentsOf: source, encoding: .utf8)
        let regions = GeneratedFile.preservedRegions(in: text)
        let names =
            [StartupConfiguration.yoursRegion].filter { regions[$0] != nil }
            + regions.keys.filter { $0 != StartupConfiguration.yoursRegion }.sorted()
        let body = StartupConfiguration.tidy(
            names.compactMap { regions[$0] }.joined(separator: "\n").components(separatedBy: "\n"))
        guard !body.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return "" }
        report.append("Carried your own commands over from \(Paths.display(source))")
        return pointingAtNewFolder(body, in: source, report: &report)
    }

    /// `text` with paths into `~/.config/macarchy` pointed at the new folder,
    /// saying so in the report.
    static func pointingAtNewFolder(
        _ text: String, in source: URL, report: inout [String]
    )
        -> String
    {
        let rewritten = LegacyLayout.rewritingOldPaths(text)
        if rewritten.changed != 0 {
            let paths = rewritten.changed == 1 ? "1 path" : "\(rewritten.changed) paths"
            report.append(
                "Pointed \(paths) from \(Paths.display(source)) at "
                    + "\(Paths.display(Paths.appRoot))")
        }
        if LegacyLayout.mentionsOldFolder(rewritten.text) {
            report.append(
                "\(Paths.display(source)) still names \(Paths.display(Paths.legacyRoot)) "
                    + "where it could not be rewritten; a link there keeps it working until "
                    + "uninstall")
        }
        return rewritten.text
    }

    /// A keep region without its end marker cannot be carried: where the
    /// person's lines stop cannot be told. Setup stops before changing
    /// anything and says how to fix it.
    static func checkCarriable() throws {
        let candidates = [
            (StartupConfiguration.yabairc.url, yabaiSource),
            (StartupConfiguration.sketchybarrc.url, sketchybarSource)
        ]
        for case (let target, let source?) in candidates
        where !isGenerated(target) && isGenerated(source) {
            let text = try String(contentsOf: source, encoding: .utf8)
            guard GeneratedFile.hasUnterminatedRegion(text) else { continue }
            throw Refused(
                reason: "\(Paths.display(source)) has a keep region without its end marker "
                    + "(\(GeneratedFile.endKeep)), so setup cannot tell which lines are yours. "
                    + "Add the marker after your own lines, then set up again. "
                    + "Setup did not change anything.")
        }
    }

    /// Moves an earlier version's folder before anything else touches the
    /// new one, and stops setup if it is still waiting to move, because
    /// setting up an empty folder would start every setting from defaults.
    static func moveEarlierFolder() throws -> [String] {
        let outcome = try LegacyLayout.move()
        guard !LegacyLayout.needsMigration else {
            throw ConfigurationError(
                "Settings from an earlier version are still in "
                    + "\(Paths.display(Paths.legacyRoot)) and could not be moved. "
                    + "Setup did not change anything.")
        }
        let moved =
            "Moved \(Paths.display(Paths.legacyRoot)) to \(Paths.display(Paths.appRoot))"
        switch outcome {
        case .nothing: return []
        case .moved: return [moved]
        case .merged(nil): return [moved]
        case .merged(let aside?):
            return [
                moved,
                "Files that were already in \(Paths.display(Paths.appRoot)) and clashed are in "
                    + Paths.display(aside)
            ]
        }
    }
}
